create role anon nologin; create role authenticated nologin;
create table profiles(id text primary key, name text, role text);
create table tournaments(id text primary key, name text not null, format text, type text, status text not null default 'draft', champion text, cup_stage text, groups_data jsonb, cup_snapshot jsonb, final_standings jsonb, economy_settings jsonb, final_prize_settings jsonb, market_balance_settings jsonb, market_settings jsonb, raw_data jsonb not null default '{}', created_at timestamptz, finished_at timestamptz, reset_at timestamptz, reset_by_profile_id text, updated_at timestamptz not null default now(), source_order int not null default 0, roster_settings jsonb);
create table teams(id text primary key, tournament_id text not null references tournaments(id) on delete cascade, profile_id text references profiles(id) on delete set null, name text not null, color text, budget numeric not null default 0, active boolean not null default true, historical boolean not null default false, lineup jsonb, raw_data jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), source_order int not null default 0, unique(tournament_id, profile_id));
create table player_ownership(tournament_id text not null references tournaments(id) on delete cascade, player_id text not null, team_id text references teams(id) on delete set null, initial_team_id text references teams(id) on delete set null, squad_role text, acquisition_source text, acquired_at timestamptz, for_sale boolean not null default false, raw_data jsonb not null default '{}', primary key(tournament_id, player_id));
create table transfers(id text primary key, tournament_id text not null references tournaments(id) on delete cascade, player_id text not null, player_name text, transfer_type text not null, from_team_id text references teams(id) on delete set null, to_team_id text references teams(id) on delete set null, offer_id text, price numeric not null default 0, market_value numeric, depreciation_pct numeric, transfer_date text, created_at timestamptz, raw_data jsonb not null default '{}');
create table financial_transactions(id text primary key, tournament_id text not null references tournaments(id) on delete cascade, team_id text not null references teams(id) on delete cascade, transaction_type text not null, amount numeric not null, balance_before numeric not null, balance_after numeric not null, label text, reference_id text, operation_id uuid, created_at timestamptz, raw_data jsonb not null default '{}', check (balance_after = balance_before + amount));
create table player_catalog_overrides(player_id text primary key, overall int, market_value numeric, updated_by_profile_id text, updated_at timestamptz not null default now(), raw_data jsonb not null default '{}', attack int, defense int, attributes jsonb not null default '{}');
